-- ═══════════════════════════════════════════════════════════
-- 페이스북 그룹 사진 → 갤러리  (사람이 나온 사진만 · 날짜순)
--   ※ 얼굴이 보이지 않는 포스터·안내문 사진은 넣지 않았습니다.
--   ※ 기존 갤러리에 이미 있는 사진, 서로 겹치는 사진은 제외했습니다.
--   ※ 같은 날짜의 앨범이 이미 있으면 새로 만들지 않고 그 앨범에 합칩니다.
-- 실행: Supabase 대시보드 → SQL Editor → 붙여넣기 → Run
-- ═══════════════════════════════════════════════════════════

delete from public.gallery_photos where org = 'OB' and storage_path like 'fb/%';
delete from public.gallery_albums where org = 'OB' and album_key like 'custom:fb-%';

on conflict (album_key) do update set title = excluded.title;

